    "text": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\uB2E8\uC77C \uD589 \uD14D\uC2A4\uD2B8\uB97C \uD5C8\uC6A9\uD569\uB2C8\uB2E4." } },
    "longText": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\uC5EC\uB7EC \uC904\uC758 \uD14D\uC2A4\uD2B8\uB97C \uD5C8\uC6A9\uD569\uB2C8\uB2E4. \uC11C\uC2DD \uC788\uB294 \uD14D\uC2A4\uD2B8\uAC00 \uD65C\uC131\uD654\uB41C \uACBD\uC6B0 \uB9C8\uD06C\uB2E4\uC6B4\uC744 \uC0AC\uC6A9\uD558\uC5EC \uD14D\uC2A4\uD2B8\uB97C \uC11C\uC2DD\uD654\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4." } },
    "linkRow": { "t": 0, "b": { "t": 2, "i": [{ "t": 3, "v": "\uD14C\uC774\uBE14 ID " }, { "t": 4, "k": "table" }, { "t": 3, "v": "\uC758 \uAD00\uB828 \uD589\uC758 \uC2DD\uBCC4\uC790 \uB610\uB294 \uAE30\uBCF8 \uD544\uB4DC \uD14D\uC2A4\uD2B8 \uAC12\uC744 \uD3EC\uD568\uD558\uB294 \uBC30\uC5F4\uC744 \uD5C8\uC6A9\uD569\uB2C8\uB2E4. \uAD00\uACC4\uAC00 \uC5C5\uB370\uC774\uD2B8\uB420 \uB54C\uB9C8\uB2E4 \uBAA8\uB4E0 \uC2DD\uBCC4\uC790\uAC00 \uC81C\uACF5\uB418\uC5B4\uC57C \uD569\uB2C8\uB2E4. \uBE48 \uBC30\uC5F4\uC774 \uC81C\uACF5\uB418\uBA74 \uBAA8\uB4E0 \uAD00\uACC4\uAC00 \uC0AD\uC81C\uB429\uB2C8\uB2E4. \uC2DD\uBCC4\uC790 \uB300\uC2E0 \uD14D\uC2A4\uD2B8 \uAC12\uC758 \uACBD\uC6B0 \uAE30\uBCF8 \uD544\uB4DC\uC5D0 \uC77C\uCE58\uD558\uB294 \uAC12\uC774 \uC788\uB294 \uD589\uC744 \uAC80\uC0C9\uD569\uB2C8\uB2E4. \uC77C\uCE58\uD558\uB294 \uD56D\uBAA9\uC774 \uC5EC\uB7EC \uAC1C \uC788\uB294 \uACBD\uC6B0 \uD14C\uC774\uBE14 \uC21C\uC11C\uB300\uB85C \uCCAB \uBC88\uC9F8 \uD56D\uBAA9\uC774 \uC120\uD0DD\uB429\uB2C8\uB2E4. \uC27C\uD45C\uB85C \uAD6C\uBD84\uB41C \uD589 \uC774\uB984\uC758 \uBB38\uC790\uC5F4\uC744 \uBCF4\uB0BC \uC218\uB3C4 \uC788\uC2B5\uB2C8\uB2E4. \uB2E8\uC77C \uD589 ID\uB9CC \uBCF4\uB0BC \uC218\uB3C4 \uC788\uC2B5\uB2C8\uB2E4." }] } },
