    "file": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": '\uC0AC\uC6A9\uC790 \uD30C\uC77C\uC758 \uC774\uB984\uC744 \uD3EC\uD568\uD558\uB294 \uCD5C\uC18C\uD55C\uC758 \uAC1D\uCCB4 \uBC30\uC5F4\uC744 \uD5C8\uC6A9\uD569\uB2C8\uB2E4. \uB610\uB294 \uC27C\uD45C\uB85C \uAD6C\uBD84\uB41C \uD30C\uC77C \uC774\uB984 \uBAA9\uB85D\uC774\uB098 \uD30C\uC77C \uC774\uB984 \uBC30\uC5F4\uC744 \uC81C\uACF5\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. "\uD30C\uC77C \uC5C5\uB85C\uB4DC" \uC5D4\uB4DC\uD3EC\uC778\uD2B8\uB97C \uC0AC\uC6A9\uD558\uC5EC \uD30C\uC77C\uC744 \uC5C5\uB85C\uB4DC\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uD574\uB2F9 \uD638\uCD9C\uC758 \uC751\uB2F5\uC744 \uC5EC\uAE30\uC5D0\uC11C \uAC1D\uCCB4\uB85C \uC9C1\uC811 \uC81C\uACF5\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC5D4\uB4DC\uD3EC\uC778\uD2B8\uB294 \uC67C\uCABD \uC0AC\uC774\uB4DC\uBC14\uC5D0\uC11C \uCC3E\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4.' } },
    "singleSelect": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\uC120\uD0DD\uD55C \uC635\uC158\uC758 ID \uB610\uB294 \uC635\uC158 \uAC12\uC744 \uB098\uD0C0\uB0B4\uB294 \uC815\uC218 \uB610\uB294 \uD14D\uC2A4\uD2B8 \uAC12\uC744 \uD5C8\uC6A9\uD569\uB2C8\uB2E4. null \uAC12\uC740 \uC544\uBB34\uAC83\uB3C4 \uC120\uD0DD\uB418\uC9C0 \uC54A\uC558\uC74C\uC744 \uC758\uBBF8\uD569\uB2C8\uB2E4. \uD14D\uC2A4\uD2B8 \uAC12\uC778 \uACBD\uC6B0, \uC77C\uCE58\uD558\uB294 \uCCAB \uBC88\uC9F8 \uC635\uC158\uC774 \uC120\uD0DD\uB429\uB2C8\uB2E4." } },
    "multipleSelect": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\uC120\uD0DD\uB41C \uC635\uC158\uC758 ID \uB610\uB294 \uAC12\uC744 \uB098\uD0C0\uB0B4\uB294 \uC815\uC218 \uB610\uB294 \uD14D\uC2A4\uD2B8 \uAC12\uC758 \uBC30\uC5F4\uC744 \uD5C8\uC6A9\uD569\uB2C8\uB2E4. \uD14D\uC2A4\uD2B8 \uAC12\uC758 \uACBD\uC6B0, \uC77C\uCE58\uD558\uB294 \uCCAB \uBC88\uC9F8 \uC635\uC158\uC774 \uC120\uD0DD\uB429\uB2C8\uB2E4. \uC27C\uD45C\uB85C \uAD6C\uBD84\uB41C \uC774\uB984 \uBB38\uC790\uC5F4\uC744 \uAC12\uC73C\uB85C \uBCF4\uB0BC \uC218 \uC788\uC73C\uBA70, \uC774 \uACBD\uC6B0 \uBB38\uC790\uC5F4\uC740 \uC635\uC158 \uC774\uB984 \uBC30\uC5F4\uB85C \uBCC0\uD658\uB429\uB2C8\uB2E4." } },
    "phoneNumber": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\uCD5C\uB300 100\uC790\uC758 \uC22B\uC790, \uACF5\uBC31 \uBC0F \uB2E4\uC74C \uBB38\uC790\uB97C \uD3EC\uD568\uD558\uB294 \uC804\uD654\uBC88\uD638\uB97C \uD5C8\uC6A9\uD569\uB2C8\uB2E4: Nx,._+*()#=;/- ." } },
    "formula": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Baserow \uC218\uC2DD \uC5B8\uC5B4\uB85C \uC791\uC131\uB41C \uC218\uC2DD\uC5D0 \uC758\uD574 \uC815\uC758\uB41C \uC77D\uAE30 \uC804\uC6A9 \uD544\uB4DC\uC785\uB2C8\uB2E4." } },
    "count": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\uB9C1\uD06C\uB41C \uD14C\uC774\uBE14 \uD544\uB4DC\uC5D0 \uC5F0\uACB0\uB41C \uC77D\uAE30 \uC804\uC6A9 \uD544\uB4DC\uB85C, \uAD00\uACC4 \uC218\uB97C \uBC18\uD658\uD569\uB2C8\uB2E4." } },
    "rollup": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\uB9C1\uD06C\uB41C \uD14C\uC774\uBE14 \uD544\uB4DC\uC5D0 \uC5F0\uACB0\uB41C \uC77D\uAE30 \uC804\uC6A9 \uD544\uB4DC\uB85C, \uB9C1\uD06C\uB41C \uD14C\uC774\uBE14\uC758 \uC120\uD0DD\uB41C \uC870\uD68C \uD544\uB4DC\uC758 \uAC12\uC744 \uB864\uC5C5\uD558\uC5EC \uBC18\uD658\uD569\uB2C8\uB2E4." } },
    "lookup": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\uC5F0\uACB0\uB41C \uD14C\uC774\uBE14 \uD544\uB4DC\uC5D0 \uC5F0\uACB0\uB41C \uC77D\uAE30 \uC804\uC6A9 \uD544\uB4DC\uB85C, \uC5F0\uACB0\uB41C \uD14C\uC774\uBE14\uC5D0\uC11C \uC120\uD0DD\uD55C \uC870\uD68C \uD544\uB4DC\uC758 \uAC12\uACFC \uD589 ID \uBC30\uC5F4\uC744 \uBC18\uD658\uD569\uB2C8\uB2E4." } },
    "multipleCollaborators": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\uAC01 \uAC1D\uCCB4\uC5D0 \uC0AC\uC6A9\uC790 ID\uAC00 \uD3EC\uD568\uB41C \uAC1D\uCCB4 \uBC30\uC5F4\uC744 \uD5C8\uC6A9\uD569\uB2C8\uB2E4." } },
    "uuid": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\uC77D\uAE30 \uC804\uC6A9\uC758 \uACE0\uC720\uD558\uACE0 \uC601\uAD6C\uC801\uC778 UUID\uC785\uB2C8\uB2E4." } },
    "autonumber": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\uAC01 \uC0C8 \uD589\uC5D0 \uB300\uD574 \uC790\uB3D9\uC73C\uB85C \uBC88\uD638\uB97C \uC99D\uAC00\uC2DC\uD0A4\uB294 \uC77D\uAE30 \uC804\uC6A9 \uD544\uB4DC\uC785\uB2C8\uB2E4." } },
    "password": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\uD574\uC2DC\uB41C \uBE44\uBC00\uBC88\uD638\uB97C \uBCF4\uC720\uD558\uB294 \uC4F0\uAE30 \uC804\uC6A9 \uD544\uB4DC\uC785\uB2C8\uB2E4. \uC124\uC815\uB418\uC9C0 \uC54A\uC740 \uACBD\uC6B0 \uAC12\uC740 `null`\uC774\uBA70, \uC124\uC815\uB41C \uACBD\uC6B0 `true`\uC785\uB2C8\uB2E4. \uBB38\uC790\uC5F4\uC744 \uBC1B\uC544\uC11C \uC124\uC815\uD569\uB2C8\uB2E4." } },
    "formViewEditRow": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\uC77D\uAE30 \uC804\uC6A9 \uD544\uB4DC\uB85C, \uC5F0\uACB0\uB41C \uC591\uC2DD \uBCF4\uAE30\uB97C \uD1B5\uD574 \uD589\uC744 \uD3B8\uC9D1\uD560 \uC218 \uC788\uB3C4\uB85D \uACE0\uC720\uD558\uACE0 \uC11C\uBA85\uB41C URL\uC744 \uC0DD\uC131\uD569\uB2C8\uB2E4." } }
