    "cannotRestoreParentBeforeChildDescription": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\uC774 \uD56D\uBAA9\uC740 \uC0AD\uC81C\uB41C \uD56D\uBAA9\uC5D0 \uC758\uC874\uD558\uAE30 \uB54C\uBB38\uC5D0 \uBCF5\uC6D0\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. \uBA3C\uC800 \uC0C1\uC704 \uD56D\uBAA9\uC744 \uBCF5\uC6D0\uD558\uC138\uC694." } },
    "cannotRestoreAsRelatedTableTrashedTitle": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\uBA3C\uC800 \uAD00\uB828 \uD14C\uC774\uBE14\uC744 \uBCF5\uC6D0\uD558\uC138\uC694." } },
    "cannotRestoreAsRelatedTableTrashedDescription": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\uB2E4\uB978 \uD14C\uC774\uBE14\uC5D0 \uC758\uC874\uD558\uAE30 \uB54C\uBB38\uC5D0 \uC774 \uD544\uB4DC\uB97C \uBCF5\uC6D0\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. \uBA3C\uC800 \uB2E4\uB978 \uAD00\uB828 \uD14C\uC774\uBE14\uC744 \uBCF5\uC6D0\uD558\uC138\uC694." } },
    "workspaceUserIsLastAdminTitle": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\uC791\uC5C5\uACF5\uAC04\uC744 \uB098\uAC08 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4" } },
    "workspaceUserIsLastAdminDescription": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\uB2E4\uB978 \uAD00\uB9AC\uC790\uC758 \uACC4\uC815\uC774 \uC0AD\uC81C \uB300\uAE30 \uC911\uC774\uAC70\uB098 \uB9C8\uC9C0\uB9C9 \uAD00\uB9AC\uC790\uC774\uAE30 \uB54C\uBB38\uC5D0 \uC791\uC5C5\uACF5\uAC04\uC744 \uB098\uAC08 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. \uC791\uC5C5\uACF5\uAC04\uC744 \uC0AD\uC81C\uD558\uAC70\uB098 \uB2E4\uB978 \uC0AC\uC6A9\uC790\uC5D0\uAC8C \uAD00\uB9AC\uC790 \uAD8C\uD55C\uC744 \uBD80\uC5EC\uD558\uC138\uC694." } },
    "errorMaxJobCountExceededTitle": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\uC791\uC5C5\uC744 \uC2DC\uC791\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4." } },
    "errorMaxJobCountExceededDescription": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\uBC31\uADF8\uB77C\uC6B4\uB4DC\uC5D0\uC11C \uC544\uC9C1 \uC2E4\uD589 \uC911\uC778 \uB2E4\uB978 \uC791\uC5C5\uC774 \uC788\uC73C\uBBC0\uB85C \uB354 \uC774\uC0C1\uC758 \uC791\uC5C5\uC744 \uC2DC\uC791\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. \uC774\uC804 \uC791\uC5C5\uC774 \uC644\uB8CC\uB420 \uB54C\uAE4C\uC9C0 \uAE30\uB2E4\uB838\uB2E4\uAC00 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694." } },
    "failedToLockFieldDueToConflictTitle": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\uD544\uB4DC\uB97C \uBCC0\uACBD\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4" } },
